#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "2mm.h"

/* Include the Exo-generated kernel header. */
#include "generated/2mm/2mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Optimized 2mm kernel:
#   D := alpha * A * B * C + beta * D
#
# The computation is structured as:
#   1) Zero-initialize tmp.
#   2) tmp = alpha * A * B      (GEMM-like, i-k-j order for row-wise locality).
#   3) Scale D by beta.
#   4) D += tmp * C             (GEMM-like, i-k-j order).
#
# Outer i-loops of all four phases are then parallelized with OpenMP via
# `parallelize_loop` to exploit multi-core CPUs while preserving semantics.

@proc
def kernel_2mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    tmp: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # Basic sanity: PolyBench sizes are positive.
    assert ni > 0
    assert nj > 0
    assert nk > 0
    assert nl > 0

    # 1) Initialize tmp to zero.
    #    This is separated from the accumulation phase to enable better
    #    scheduling and parallelization.
    for i in seq(0, ni):
        for j in seq(0, nj):
            tmp[i, j] = 0.0

    # 2) tmp := alpha * A * B
    #
    # Loop order i-k-j improves spatial locality:
    #   - A[i, k] is read once per (i, k) and multiplied by alpha.
    #   - B[k, j] and tmp[i, j] are traversed with j innermost, giving
    #     contiguous row-wise access in row-major layout.
    for i in seq(0, ni):
        for k in seq(0, nk):
            a_ik: DATA_TYPE
            a_ik = alpha * A[i, k]
            for j in seq(0, nj):
                tmp[i, j] += a_ik * B[k, j]

    # 3) Scale D by beta.
    #    Kept as a separate phase to maintain a simple, parallelizable loop.
    for i in seq(0, ni):
        for j in seq(0, nl):
            D[i, j] = beta * D[i, j]

    # 4) D += tmp * C
    #
    # Again use i-k-j order:
    #   - tmp[i, k] is loaded once per (i, k) and reused across all j.
    #   - C[k, j] and D[i, j] are traversed row-wise in the inner j-loop.
    for i in seq(0, ni):
        for k in seq(0, nj):
            t_ik: DATA_TYPE
            t_ik = tmp[i, k]
            for j in seq(0, nl):
                D[i, j] += t_ik * C[k, j]


# Scheduling: parallelize the outer i-loops of all four phases.
# Each i-slice operates on disjoint rows of tmp and D, so this is
# embarrassingly parallel and safe.
kernel_2mm = parallelize_loop(kernel_2mm, "i #0")  # zeroing tmp
kernel_2mm = parallelize_loop(kernel_2mm, "i #1")  # tmp = alpha * A * B
kernel_2mm = parallelize_loop(kernel_2mm, "i #2")  # scale D
kernel_2mm = parallelize_loop(kernel_2mm, "i #3")  # D += tmp * C

# Apply compiler-driven simplifications (CSE, constant folding, etc.)
# after scheduling to clean up the IR.
kernel_2mm = simplify(kernel_2mm)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_2mm (/*ctxt=*/NULL, ni, nj, nk, nl,
	      (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	      (DATA_TYPE*)POLYBENCH_ARRAY(tmp),
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(B),
	      (DATA_TYPE*)POLYBENCH_ARRAY(C),
	      (DATA_TYPE*)POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
